"""Explicit text-to-tag matching. No report recovery, extra parsing or inference."""
import copy
import re

from r3.round3.claims import present

BOOKKEEPING = {"region_id", "instance_id", "entity_type", "identity_certainty", "instance_role"}
EXCLUDED_FIELDS = {"source_laterality", "anatomic_region", "posterior_acoustic_feature"}
NEGATION = re.compile(r"\b(?:no|not|without|absent|lacks?|lack of|loss of)\b", re.I)
UNCERTAINTY = re.compile(r"\b(?:possible|possibly|suspected|suspect|probably|probable|appears? to|may|cannot exclude)\b", re.I)
BOUNDARY = re.compile(r"[.;!?]|\b(?:but|however|whereas|although)\b", re.I)
PLACEHOLDER = re.compile(r"_[A-Za-z0-9]+_", re.I)


def validate_taxonomy(taxonomy):
    ids, definitions = set(), {}
    for attr in taxonomy["attributes"]:
        assert attr["id"] == attr["entity_type"] + "." + attr["source_attribute"]
        assert attr["id"] not in ids
        assert attr["source_attribute"] not in EXCLUDED_FIELDS | {"extra_attributes"}
        assert not attr["source_attribute"].startswith("extra_attributes.")
        ids.add(attr["id"])
        group_ids = set()
        for group in attr["groups"]:
            assert group["group_id"] not in group_ids
            group_ids.add(group["group_id"])
            assert group["selection"] in {"single", "multiple"}
            assert group["multi_label"] == (group["selection"] == "multiple")
            assert group["decision_unit"] == "one_entity_one_attribute_one_group"
            assert group["selection_reason"].strip()
            assert group["tags"] and len({t["tag"] for t in group["tags"]}) == len(group["tags"])
            signature = (group["selection"], tuple(t["tag"] for t in group["tags"]))
            if group["benchmark_id"] in definitions:
                assert definitions[group["benchmark_id"]] == signature
            definitions[group["benchmark_id"]] = signature
            for tag in group["tags"]:
                assert tag["definition"].strip() and tag["label_zh"].strip()
                assert "value" not in tag and "score" not in tag
                assert tag["patterns"]
                for pattern in tag["patterns"]:
                    re.compile(pattern["regex"], re.I)
            for pattern in group.get("excluded_patterns", []):
                re.compile(pattern, re.I)
            assert set(group.get("allow_uncertain_tags", [])) <= {t["tag"] for t in group["tags"]}
            for pattern in group.get("non_target_cue_patterns", []):
                re.compile(pattern, re.I)
    assert definitions["anatomic_region.laterality"] == ("single", ("left", "right"))
    assert definitions["anatomic_region.anatomy"] == ("single", ("lobe", "isthmus", "neck"))
    return definitions


def clause_prefix(text, start):
    prefix = text[:start]
    boundaries = list(BOUNDARY.finditer(prefix))
    return prefix[boundaries[-1].end():] if boundaries else prefix


def sentence_ranges(value):
    """Preserve original offsets; a decimal is not a sentence boundary."""
    start = 0
    for separator in re.finditer(r"(?<=[.!?])\s+(?=[A-Za-z])|[;；]\s*", value):
        yield start, value[start:separator.start()]
        start = separator.end()
    yield start, value[start:]


def match_group(value, group):
    base = {"benchmark_id": group["benchmark_id"], "group_id": group["group_id"],
            "selection": group["selection"], "ordered": group["ordered"],
            "tags": [], "candidate_tags": [], "matched_evidence": [], "suppressed_evidence": []}
    exclusions = [p for p in group.get("excluded_patterns", []) if re.search(p, value, re.I)]
    if exclusions:
        return {**base, "status": "excluded", "reason": "group_contract_exclusion", "exclusion_patterns": exclusions}
    hits = []
    for tag in group["tags"]:
        for pattern in tag["patterns"]:
            for offset, sentence in sentence_ranges(value):
                for m in re.finditer(pattern["regex"], sentence, re.I):
                    hit = {"tag": tag["tag"], "span": [offset + m.start(), offset + m.end()], "text": m.group(),
                           "pattern": pattern["regex"], "priority": pattern["priority"]}
                    local = [p for p in group.get("non_target_cue_patterns", [])
                             if any(x.start() <= m.start() and x.end() >= m.end()
                                    for x in re.finditer(p, sentence, re.I))]
                    if local:
                        base["suppressed_evidence"].append({**hit, "reason": "local_component_not_overall_entity",
                                                             "scope_patterns": local})
                        continue
                    prefix = clause_prefix(sentence, m.start())
                    if NEGATION.search(prefix) and not NEGATION.search(m.group()):
                        base["suppressed_evidence"].append({**hit, "reason": "negated_positive_cue"})
                        continue
                    hit["uncertain"] = bool(UNCERTAINTY.search(prefix + m.group())) and tag["tag"] not in group.get("allow_uncertain_tags", [])
                    hits.append(hit)
    remaining = []
    for hit in hits:
        # Priority resolves nested wording only, never separate contradictory clauses.
        shadow = any(other["tag"] != hit["tag"] and other["span"][0] < hit["span"][1]
            and other["span"][1] > hit["span"][0]
            and (other["priority"] > hit["priority"] or
                 other["priority"] == hit["priority"] and other["span"][0] <= hit["span"][0]
                 and other["span"][1] >= hit["span"][1] and other["span"] != hit["span"])
            for other in hits)
        if shadow:
            base["suppressed_evidence"].append({**hit, "reason": "covered_by_more_specific_cue"})
        else:
            remaining.append(hit)
    # Explicit refinement relationships, not a blanket highest-priority winner.
    # Example: predominantly-solid refines mixed-cystic-solid; solid does not
    # refine cystic. Separate incompatible states still remain ambiguous.
    for specific, general in group.get("refines", {}).items():
        if any(h["tag"] == specific and not h["uncertain"] for h in remaining):
            suppressed = [h for h in remaining if h["tag"] in general]
            base["suppressed_evidence"].extend({**h, "reason": "explicit_taxonomy_refinement", "refined_by": specific} for h in suppressed)
            remaining = [h for h in remaining if h["tag"] not in general]
    by_tag = {t["tag"] for t in group["tags"] if any(h["tag"] == t["tag"] for h in remaining)}
    selected = [t["tag"] for t in group["tags"] if t["tag"] in by_tag]
    base.update(candidate_tags=selected, matched_evidence=remaining)
    if not selected:
        if group["benchmark_id"] == "anatomic_region.laterality" and value.strip().lower() == "isthmus":
            return {**base, "status": "not_applicable", "reason": "isthmus_has_no_left_right_tag"}
        return {**base, "status": "unmatched"}
    if group["selection"] == "single" and len(selected) > 1:
        return {**base, "status": "ambiguous", "reason": "incompatible_single_group_cues"}
    certain = [tag for tag in selected if any(not h["uncertain"] for h in remaining if h["tag"] == tag)]
    uncertain = [tag for tag in selected if tag not in certain]
    # Explicit uncertain tags (e.g. possibly-visible) are labels of uncertainty,
    # not a claim that the unqualified positive finding is definitely visible.
    if uncertain:
        return {**base, "tags": certain if group["selection"] == "multiple" else [],
                "status": "ambiguous", "reason": "uncertain_wording", "uncertain_candidate_tags": uncertain}
    return {**base, "tags": selected, "status": "assigned"}


def annotate_attribute(item, spec):
    if spec is None:
        return {**item, "annotation_status": "unconfigured_attribute", "group_annotations": [],
                "gap_reason": "unconfigured_direct_attribute"}
    groups = [match_group(item["report_value"], g) for g in spec["groups"]]
    if item["attribute"] in {"anatomy", "laterality"} and item["report_value"].strip().lower() not in spec["allowed_scalar_values"]:
        # A single entity's position is not an image-level coverage set.
        groups = [{**g, "tags": [], "status": "ambiguous",
                   "reason": "noncanonical_or_multi_entity_position"} for g in groups]
    statuses = {g["status"] for g in groups}
    if "assigned" in statuses:
        status = "assigned"
    elif "ambiguous" in statuses:
        status = "ambiguous"
    elif "excluded" in statuses:
        status = "excluded"
    else:
        status = "unmatched_value"
    # Measurements/placeholders without qualitative wording are not clinical tags.
    if status == "unmatched_value" and item["attribute"] in {"size", "thickness", "orientation"}:
        if PLACEHOLDER.search(item["report_value"]) or re.search(r"\b\d+(?:\.\d+)?\s*(?:mm|cm)\b", item["report_value"], re.I):
            status = "excluded"
            return {**item, "annotation_status": status, "group_annotations": groups,
                    "exclusion_reason": "measurement_or_placeholder_has_no_qualitative_tag"}
    result = {**item, "annotation_status": status, "group_annotations": groups}
    if status in {"unmatched_value", "unconfigured_attribute"}:
        result["gap_reason"] = "taxonomy_unmatched"
    return result


def entity_items(entity, identity, entity_kind):
    id_key = "region_id" if entity_kind == "region" else "instance_id"
    fixed = {**identity, "entity_kind": entity_kind, "entity_type": entity["entity_type"],
             "entity_id": entity[id_key], "entity_ref": identity["record_id"] + "/" + entity_kind + "/" + entity[id_key]}
    items, exclusions = [], []
    for name, value in entity.items():
        if name in BOOKKEEPING:
            continue
        if name == "extra_attributes":
            exclusions.append({**fixed, "attribute": name, "reason": "user_excludes_all_extra_attributes",
                               "excluded_entry_count": len(value or [])})
            continue
        if name in EXCLUDED_FIELDS or entity_kind == "instance" and name == "size":
            if present(value):
                exclusions.append({**fixed, "attribute": name, "reason": "outside_current_benchmark_scope"})
            continue
        if not present(value):
            exclusions.append({**fixed, "attribute": name, "reason": "missing_none_or_rejected"})
            continue
        if not isinstance(value, str):
            raise ValueError(f"Non-string direct attribute: {fixed['entity_ref']}/{name}")
        items.append({**fixed, "attribute": name, "attribute_id": entity["entity_type"] + "." + name,
                      "report_value": value})
    return items, exclusions


def iter_entities(row, level):
    uid = str(row["uid"])
    if level == "image":
        fixed = {"uid": uid, "split": row["split"], "source_level": level,
                 "image_id": row["image_id"], "record_id": uid + "/" + row["image_id"]}
        for kind, collection in (("region", "regions"), ("instance", "instances")):
            for e in row.get(collection) or []:
                yield e, fixed, kind
    elif level == "case":
        report = row["structured_report"]
        for e in report["regions"]:
            yield e, {"uid": uid, "split": row["split"], "source_level": level,
                      "image_id": None, "record_id": uid + "/case"}, "region"
        for image_id, entities in report["instances_by_image"].items():
            for e in entities or []:
                yield e, {"uid": uid, "split": row["split"], "source_level": level,
                          "image_id": image_id, "record_id": uid + "/case/" + image_id}, "instance"
    else:
        raise ValueError("Invalid level")


def process_record(row, level, spec_index):
    attributes, exclusions, ids = [], [], set()
    partial = row.get("claim_filtering_status", row.get("status")) != "complete"
    for entity, identity, kind in iter_entities(row, level):
        identity = {**identity, "source_status": "partial_upstream" if partial else "complete"}
        items, excluded = entity_items(entity, identity, kind)
        ref = identity["record_id"] + "/" + kind + "/" + entity["region_id" if kind == "region" else "instance_id"]
        if ref in ids:
            raise ValueError("Duplicate entity identity: " + ref)
        ids.add(ref)
        attributes.extend(annotate_attribute(i, spec_index.get(i["attribute_id"])) for i in items)
        exclusions.extend(excluded)
    result = {"uid": str(row["uid"]), "split": row["split"], "source_level": level,
              "status": "partial_upstream" if partial else "complete",
              "attribute_annotations": attributes, "entity_count": len(ids)}
    if level == "image":
        result.update(image_id=row["image_id"], image_index=row["image_index"],
                      structured_report={"regions": copy.deepcopy(row["regions"]), "instances": copy.deepcopy(row["instances"])},
                      region_bindings=copy.deepcopy(row["region_bindings"]))
    else:
        result.update(image_ids=row["image_ids"], structured_report=copy.deepcopy(row["structured_report"]),
                      region_bindings=copy.deepcopy(row["region_bindings"]))
    return result, exclusions


def tag_rows(attributes):
    for attr in attributes:
        fixed = {k: v for k, v in attr.items() if k not in {"annotation_status", "group_annotations", "gap_reason", "exclusion_reason"}}
        for group in attr["group_annotations"]:
            if group["status"] != "assigned":
                continue
            for tag in group["tags"]:
                yield {**fixed, "benchmark_id": group["benchmark_id"], "group_id": group["group_id"],
                       "selection": group["selection"], "tag": tag,
                       "evidence": [h for h in group["matched_evidence"] if h["tag"] == tag and not h["uncertain"]]}
